비대해질 때를 미리 걱정하는 점 정말 좋아요. 
보통 실무에서는 도메인별 enum 을 분리해서 따로 관리하다가 비대해지면 체계화 하는 방식으로 진행하는 것 같아요.

```java
 // 공통 인터페이스                                                                                                                                             
  public interface ErrorCode {                                                                                                                                   
      HttpStatus getStatus();
      String getMessage();                                                                                                                                       
  }                                                                                                                                                            

  // 도메인별로 분리
  public enum ReservationErrorCode implements ErrorCode {                                                                                                        
      NOT_FOUND(NOT_FOUND, "존재하지 않는 예약입니다."),
      DUPLICATE(CONFLICT, "이미 예약된 시간입니다.");                                                                                                            
  }                                                                                                                                                            

  public enum TimeErrorCode implements ErrorCode {                                                                                                               
      NOT_FOUND(NOT_FOUND, "존재하지 않는 시간대입니다."),
      IN_USE(CONFLICT, "예약이 존재하는 시간대입니다.");                                                                                                         
  }                                                                                                                                                            

  // Handler는 인터페이스만 바라봄                                                                                                                             
  @ExceptionHandler                                                                                                                                              
  public ResponseEntity<ErrorResponse> handle(RoomescapeException e) {
      ErrorCode code = e.getErrorCode();  // 어떤 enum이든 상관없음                                                                                              
      return ErrorResponse.of(code);                                                                                                                             
  }                          
```


