    reservationService.save(new ReservationRequest("밀란", LocalDate.of(2026, 5, 6), time1.getId(), theme.getId()));

    // When
    List<ReservationTime> available = reservationTimeService.findAvailableReservationTimes(...);

    // Then
    assertThat(available).containsExactly(time2);
}
```

