@SpringBootTest
class DistributedLockAspectTest {

    @Autowired LockProvider lockProvider;

    @Test
    void 같은_key_에_대해_동시_진입을_막는다() throws Exception {
        CountDownLatch firstAcquired = new CountDownLatch(1);
        CountDownLatch allowFirstRelease = new CountDownLatch(1);
        AtomicBoolean secondAcquired = new AtomicBoolean(false);

        ExecutorService pool = Executors.newFixedThreadPool(2);

        pool.submit(() -> {
            lockProvider.tryAcquire("reservation:1", 1000, 30000);
            firstAcquired.countDown();
            try { allowFirstRelease.await(2, TimeUnit.SECONDS); }
            catch (InterruptedException e) { Thread.currentThread().interrupt(); }
            lockProvider.release("reservation:1");
        });

        firstAcquired.await(1, TimeUnit.SECONDS);

        Future<Boolean> second = pool.submit(() ->
                lockProvider.tryAcquire("reservation:1", 200, 30000));

        assertThat(second.get(1, TimeUnit.SECONDS)).isFalse();
        assertThat(secondAcquired).isFalse();

        allowFirstRelease.countDown();
        pool.shutdown();
    }
}
